<?php
// Existing order events retain the platform report separately from warehouse confirmation.
function oa_deferred($status){return in_array($status,['Cancelled','Failed Delivery','Return / Refund'],true);}
function oa_reported($o){if(!isset($GLOBALS['OA_REPORTS'])){$GLOBALS['OA_REPORTS']=[];foreach(db()->query("SELECT e.order_id,e.details_json FROM om_events e JOIN (SELECT MAX(id) id FROM om_events WHERE event_type='Platform status reported' GROUP BY order_id) x ON x.id=e.id") as $e)$GLOBALS['OA_REPORTS'][$e['order_id']]=json_decode($e['details_json'],true)?:[];}return $GLOBALS['OA_REPORTS'][$o['id']]??['status'=>$o['platform_status'],'since'=>$o['status_changed_at'],'snapshot'=>$o['last_snapshot']];}
function oa_received_complete($o){$tot=om_existing_totals($o['id']);if(!$tot)return false;foreach($tot as $pid=>$qty)if(order_return_balance($o['platform'],$o['order_no'],$pid)['returned']<$qty)return false;return true;}
function oa_pending($o){$r=oa_reported($o);if(!oa_deferred($r['status']))return false;if($o['posting']==='Reversed')return false;if($r['status']==='Cancelled'&&$o['platform_status']==='Cancelled'&&$o['posting']==='Not Posted'&&$o['monitoring']==='Resolved')return false;if(oa_received_complete($o)||in_array($o['aftersales_resolution'],['Refund Only'],true))return false;return true;}
function oa_record_report($o,$status,$snapshot,$upload){$old=oa_reported($o);$since=$old['status']===$status?$old['since']:date('Y-m-d H:i:s');om_event($o['id'],$upload,'Platform status reported',['status'=>$status,'since'=>$since,'snapshot'=>$snapshot,'stock_changed'=>false]);$GLOBALS['OA_REPORTS'][$o['id']]=['status'=>$status,'since'=>$since,'snapshot'=>$snapshot];}
function oa_aging($o,$today=null){$today=$today??date('Y-m-d');$s=$o['platform_status'];$since=$o['status_changed_at']?:$o['created_at'];if($s==='To Ship')$since=$o['fulfillment_date'];$days=max(0,(int)((strtotime($today)-strtotime(substr($since,0,10)))/86400));$threshold=['To Ship'=>3,'Shipped'=>8][$s]??null;$active=$o['monitoring']!=='Resolved'&&$o['posting']!=='Reversed';return ['days'=>$days,'since'=>substr($since,0,10),'threshold'=>$threshold,'aging'=>$active&&$threshold!==null&&$days>=$threshold];}
function oa_status_badge($o){$a=oa_aging($o);$s=$o['platform_status'];$color=match($s){'To Ship','Unpaid'=>'yellow','Shipped'=>'blue','Delivered'=>'green','Completed'=>'darkgreen','Cancelled'=>'orange','Failed Delivery','Return / Refund'=>'purple','Needs Checking'=>'red',default=>'gray'};if($a['aging'])$color='red';return '<span class="oa-status oa-'.$color.'">'.e($s.($a['aging']?' · Aging '.$a['days'].' days':'')).'</span>'.(($o['aftersales_resolution']??'')==='Receipt Linked'?'<span class="oa-status oa-gray">Return Received</span>':'');}
function oa_detail($o){$a=oa_aging($o);$r=oa_reported($o);echo '<link rel="stylesheet" href="assets/order_aging.css?v=5.9.11"><div class="card"><h3>Status &amp; Aging</h3>'.oa_status_badge($o).'<p>Platform-reported: <b>'.e($r['status']).'</b> · Confirmed: '.e($o['platform_status']).'</p><p>Status unchanged since '.e($a['since']).' · '.$a['days'].' calendar days'.($a['threshold']!==null?' · Red at '.$a['threshold'].' days':'').'</p>';if(oa_pending($o))echo '<p class="alert warn">'.e($o['posting']==='Not Posted'?'For cancellation confirmation / review. Reservation stays held until confirmed.':'Awaiting physical return. Stock will only increase after actual receiving.').'</p><a class="btn secondary" href="?page=inflow&amp;entry=manual&amp;pending_order='.(int)$o['id'].'">Review in Inflow</a>';echo '</div>';}
function oa_confirm_cancellation($id,$input){if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');if(empty($input['warehouse_ack']))throw new Exception('Confirm that no dispatch was posted and the units remain in the warehouse.');return process_transaction(function()use($id,$input){$o=om_order($id,true);$r=oa_reported($o);if($r['status']!=='Cancelled'||$o['posting']!=='Not Posted'||!oa_pending($o))throw new Exception('This order is not awaiting a pre-dispatch cancellation confirmation.');$reason=process_reason($input['reason']??'');if(om_query('SELECT COUNT(*) FROM om_postings WHERE order_id=?',[$id])->fetchColumn())throw new Exception('A dispatch posting exists. Use physical receiving instead.');om_release_all($id,'Cancellation confirmed in Inflow');om_query("UPDATE om_orders SET platform_status='Cancelled',status_changed_at=NOW(),monitoring='Resolved',exception_text='',revision=revision+1 WHERE id=?",[$id]);om_event($id,null,'Cancellation confirmed in Inflow',['reason'=>$reason,'physical_delta'=>0,'reservation_released'=>true]);audit('Confirm cancellation in Inflow','Order Monitoring',$o['order_no'],$reason.'; reservation released; physical unchanged.');om_alert_refresh();});}
function oa_refund_only($id,$input){if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');if(empty($input['no_return_ack']))throw new Exception('Confirm no physical stock is being returned.');return process_transaction(function()use($id,$input){$o=om_order($id,true);$r=oa_reported($o);if($o['posting']!=='Posted'||!oa_pending($o))throw new Exception('This order has no pending post-dispatch return resolution.');$reason=process_reason($input['reason']??'');om_query("UPDATE om_orders SET status_changed_at=IF(platform_status<>?,NOW(),status_changed_at),platform_status=?,monitoring='Resolved',aftersales_resolution='Refund Only',exception_text='',revision=revision+1 WHERE id=?",[$r['status'],$r['status'],$id]);om_event($id,null,'Refund only confirmed in Inflow',['reason'=>$reason,'physical_delta'=>0]);audit('Confirm refund-only outcome','Order Monitoring',$o['order_no'],$reason.'; no physical receipt or stock addition.');om_alert_refresh();});}
function oa_receipt_reconcile($platform,$no,$batch=null){if(!om_ready())return;$o=om_find($platform,om_shops()[$platform]??'',$no);if(!$o)return;$r=oa_reported($o);if(!oa_pending($o)&&!oa_received_complete($o))return;if(oa_received_complete($o)){if(oa_deferred($r['status']))om_query("UPDATE om_orders SET status_changed_at=IF(platform_status<>?,NOW(),status_changed_at),platform_status=?,monitoring='Resolved',exception_text='',aftersales_resolution='Receipt Linked',revision=revision+1 WHERE id=?",[$r['status'],$r['status'],$o['id']]);elseif($o['platform_status']==='Cancelled')om_query("UPDATE om_orders SET monitoring='Resolved',exception_text='',aftersales_resolution='Receipt Linked',revision=revision+1 WHERE id=?",[$o['id']]);}elseif(oa_deferred($r['status']))om_query("UPDATE om_orders SET monitoring='Needs Follow-up',exception_text='Awaiting remaining physical return',revision=revision+1 WHERE id=?",[$o['id']]);}
function oa_inflow_panel(){if(!om_ready()||!can_action('return_confirm'))return;$rows=[];foreach(db()->query('SELECT * FROM om_orders ORDER BY fulfillment_date,id') as $o)if(oa_pending($o)&&(!isset($_GET['pending_order'])||(int)$_GET['pending_order']===(int)$o['id']))$rows[]=$o;if(!$rows)return;$offset=max(0,(int)($_GET['pending_offset']??0));echo '<div class="card"><h3>Cancellation / Return Follow-up</h3><p>Confirm cancellation before dispatch, or receive actual returned units after dispatch. A status upload does not add stock.</p><div class="table-wrap"><table class="table"><thead><tr><th>Platform / Order</th><th>Platform-reported</th><th>Next Action</th></tr></thead><tbody>';foreach(array_slice($rows,$offset,10) as $o){$r=oa_reported($o);echo '<tr><td>'.e($o['platform'].' · '.$o['order_no']).'</td><td>'.e($r['status']).'</td><td><form method="post" action="actions.php">';if($o['posting']==='Not Posted'&&$r['status']==='Cancelled'){workflow_hidden('receiving_confirm_cancellation',['order_record_id'=>$o['id'],'return'=>'inflow&entry=manual']);echo '<label>Reason<input name="reason" minlength="3" required></label><label class="ack"><input type="checkbox" name="warehouse_ack" value="1" required> Items remain in the warehouse; no dispatch was posted.</label><button class="btn secondary">Confirm Cancellation · Physical 0</button>';}elseif($o['posting']==='Posted'){workflow_hidden('receiving_load_reported',['order_record_id'=>$o['id'],'return'=>'inflow&entry=manual']);echo '<button class="btn secondary">Receive Actual Returned Items</button>';}else echo '<p>Check original dispatch / cancellation. No stock receipt is permitted without a posted outflow.</p>';echo '</form>';if($o['posting']==='Posted'){echo '<details><summary>Refund only / no physical return</summary><form method="post" action="actions.php">';workflow_hidden('receiving_refund_only',['order_record_id'=>$o['id'],'return'=>'inflow&entry=manual']);echo '<label>Verified outcome / reference<input name="reason" minlength="3" required></label><label class="ack"><input type="checkbox" name="no_return_ack" value="1" required> Refund only; no units will be received or added to inventory.</label><button class="btn secondary">Confirm Refund Only · Physical 0</button></form></details>';}echo '</td></tr>';}echo '</tbody></table></div>'.rs8_pagination(count($rows),$offset,10,$_GET,'pending_offset').'</div>';}
function oa_receipt_check($b,$rows){$seen=[];$currentId=(int)($b['id']??0);foreach($rows as $r){$ref=unlinked_return_reference($r['receipt_reference']??'');$key=$r['platform'].'|'.$ref;$identity=$r['order'];if(isset($seen[$key])&&$seen[$key]!==$identity)throw new Exception('One tracking / receipt reference cannot identify different orders in this batch.');$seen[$key]=$identity;}
 if(!$seen)return;$q=db()->prepare("SELECT id,batch_ref,rows_json FROM return_batches WHERE status IN ('Review','Posted') AND id<>?");$q->execute([$currentId]);foreach($q as $old)foreach(json_decode($old['rows_json'],true)?:[] as $r){if(empty($r['receipt_reference']))continue;$key=($r['platform']??'').'|'.unlinked_return_reference($r['receipt_reference']);if(isset($seen[$key]))throw new Exception('Receipt already exists in '.$old['batch_ref'].' (#'.$old['id'].'). Open and link the existing receipt; do not receive it again.');}
 // An unresolved receipt for the same product/platform needs a source check before a second receipt.
 foreach($rows as $r){if(!empty($r['unlinked_receipt']))continue;$q=db()->prepare("SELECT b.id,b.batch_ref,b.rows_json FROM posted_returns p JOIN return_batches b ON b.id=p.batch_id WHERE p.platform=? AND p.product_id=? AND p.reversed=0 AND p.batch_id<>?");$q->execute([$r['platform'],$r['product_id'],$currentId]);foreach($q as $old)foreach(json_decode($old['rows_json'],true)?:[] as $or)if(!empty($or['unlinked_receipt'])&&empty($or['linked_order'])&&(int)$or['product_id']===(int)$r['product_id']){if(empty($r['separate_receipt_ack']))throw new Exception('An unlinked receipt for this product exists: '.$old['batch_ref'].' (#'.$old['id'].'). Link it first, or confirm a separate parcel with a different receipt reference.');}}
}
